<?php

declare(strict_types=1);
require __DIR__ . DIRECTORY_SEPARATOR . 'config.php';
$admin = require_admin();
$userId = trim((string) ($_GET['user'] ?? $_POST['user'] ?? ''));
$selected = null;
foreach (users() as $candidate) if (($candidate['id'] ?? '') === $userId) { $selected = $candidate; break; }
if ($selected === null) { http_response_code(404); exit('User not found.'); }
$error = '';
$notice = (string) ($_GET['notice'] ?? '');
if ($_SERVER['REQUEST_METHOD'] === 'POST' && ($_POST['action'] ?? '') === 'course_access') {
    try {
        $course = trim((string) ($_POST['course'] ?? ''));
        $restore = ($_POST['access'] ?? '') === 'restore';
        admin_set_course_access($userId, $course, $restore, (string) $admin['id'], (string) ($_POST['reason'] ?? 'Admin course access change'));
        header('Location: admin-user-detail.php?user=' . rawurlencode($userId) . '&notice=' . rawurlencode($restore ? 'Course access restored.' : 'Course access deactivated.'));
        exit;
    } catch (Throwable $exception) { $error = $exception->getMessage(); }
}
$selected = null;
foreach (users() as $candidate) if (($candidate['id'] ?? '') === $userId) { $selected = $candidate; break; }
$catalog = published_banking_catalog();
$subscriptions = user_subscriptions($userId);
$premium = null;
foreach ($subscriptions as $subscription) if (subscription_is_current($subscription)) { $premium = $subscription; break; }
$attemptStats = [];
foreach ((array) ($selected['attempts'] ?? []) as $attempt) {
    $slug = (string) ($attempt['product'] ?? '');
    if (!isset($attemptStats[$slug])) $attemptStats[$slug] = ['count' => 0, 'total' => 0, 'last' => null];
    $attemptStats[$slug]['count']++;
    $attemptStats[$slug]['total'] += (int) ($attempt['percentage'] ?? 0);
    $attemptStats[$slug]['last'] = $attempt['submitted_at'] ?? $attemptStats[$slug]['last'];
}
$courseSlugs = array_keys($catalog);
if ($premium === null) $courseSlugs = array_values(array_unique(array_merge((array) ($selected['enrolled'] ?? []), array_keys((array) ($selected['revoked_courses'] ?? [])), array_keys($attemptStats))));
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= e($selected['name']) ?> | Admin user detail</title><style>:root{--navy:#16233f;--maroon:#9c3b2e;--paper:#efece2;--card:#f8f6ee;--ink:#1c1a15;--muted:#625e50;--line:#cfc7ac;--gold:#a97a24;--green:#286447;--red:#70251c}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:15px Arial}header{background:var(--navy);border-bottom:3px solid var(--gold);padding:16px 5%;display:flex;justify-content:space-between;gap:18px}.brand{font:700 1.4rem Georgia;color:#fff;text-decoration:none}.nav{display:flex;gap:16px;flex-wrap:wrap}.nav a{color:#f5ead2;text-decoration:none}.wrap{width:min(1200px,calc(100% - 32px));margin:auto;padding:34px 0 70px}h1,h2{font-family:Georgia;color:var(--navy)}h1{font-size:clamp(2rem,4vw,3.1rem);margin:0 0 7px}.muted{color:var(--muted)}.panel{background:var(--card);border:1px solid var(--line);padding:22px;margin-top:18px}.summary{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.metric{background:var(--card);border:1px solid var(--line);padding:16px}.metric strong{display:block;color:var(--maroon);font:700 1.5rem Georgia}.metric span{font-size:.76rem;color:var(--muted)}.premium{border-left:5px solid var(--maroon);background:#fff3ed;padding:14px;color:#70251c}.notice,.error{padding:12px;margin:14px 0}.notice{background:#e0f0e6;color:#174b32}.error{background:#f7ded8;color:var(--red)}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:11px 8px;border-top:1px solid var(--line);vertical-align:middle}th{font-size:.72rem;color:var(--muted);text-transform:uppercase}.small{display:block;color:var(--muted);font-size:.78rem;margin-top:3px}.pill{display:inline-block;padding:4px 8px;background:#e0f0e6;color:var(--green);font-size:.72rem;font-weight:700}.pill.off{background:#f0e6df;color:var(--red)}.btn{border:0;background:var(--maroon);color:#fff;padding:8px 11px;font-weight:700;cursor:pointer;text-decoration:none;display:inline-block}.restore{background:var(--green)}@media(max-width:800px){.summary{grid-template-columns:repeat(2,1fr)}}@media(max-width:600px){.wrap{padding-top:24px}.summary{grid-template-columns:1fr}.panel{padding:16px}table{display:block;overflow-x:auto;white-space:nowrap}}
</style></head><body><header><a class="brand" href="admin-course-control.php">Course access control</a><nav class="nav"><a href="admin.php">Control centre</a><a href="admin-course-control.php">All users</a><a href="logout.php">Log out</a></nav></header><main class="wrap"><a class="muted" href="admin-course-control.php">&larr; Back to all users</a><h1><?= e($selected['name']) ?></h1><p class="muted"><?= e($selected['email']) ?> · User ID <?= e($userId) ?></p><?php if($notice!==''): ?><div class="notice"><?= e($notice) ?></div><?php endif; ?><?php if($error!==''): ?><div class="error"><?= e($error) ?></div><?php endif; ?><?php if($premium!==null): ?><div class="premium"><strong>Premium user: <?= e((string)($premium['plan_name']??'Premium subscription')) ?></strong><br>Active until <?= e(date('d M Y',strtotime((string)$premium['expires_at']))) ?> · Access includes the eligible courses in this plan unless individually revoked.</div><?php else: ?><div class="panel"><strong>No active premium subscription.</strong><span class="muted"> Course access is based on recorded enrollments.</span></div><?php endif; ?><section class="summary" style="margin-top:18px"><div class="metric"><strong><?= count((array)($selected['enrolled']??[])) ?></strong><span>active enrollments</span></div><div class="metric"><strong><?= count((array)($selected['orders']??[])) ?></strong><span>orders</span></div><div class="metric"><strong><?= count((array)($selected['attempts']??[])) ?></strong><span>attempts</span></div><div class="metric"><strong><?= count($subscriptions) ?></strong><span>subscriptions</span></div></section><section class="panel"><h2>Course access and performance</h2><p class="muted">Revoking access never deletes attempts, orders, invoices or subscription records.</p><?php if($courseSlugs===[]): ?><p class="muted">No course activity recorded.</p><?php else: ?><table><thead><tr><th>Course</th><th>Access</th><th>Attempts</th><th>Average</th><th>Last attempt</th><th>Action</th></tr></thead><tbody><?php foreach($courseSlugs as $slug): $stats=$attemptStats[$slug]??['count'=>0,'total'=>0,'last'=>null];$revoked=!empty(((array)($selected['revoked_courses']??[]))[$slug]);$active=!$revoked && ($premium!==null || in_array($slug,(array)($selected['enrolled']??[]),true)); ?><tr><td><?= e((string)($catalog[$slug]['title']??$slug)) ?><span class="small"><?= e($slug) ?></span></td><td><span class="pill <?= $active?'':'off' ?>"><?= $active?'Active':'Revoked / not enrolled' ?></span></td><td><?= (int)$stats['count'] ?></td><td><?= $stats['count']?(int)round($stats['total']/$stats['count']):0 ?>%</td><td><?= $stats['last']===null?'None':e(date('d M Y H:i',strtotime((string)$stats['last']))) ?></td><td><form method="post" onsubmit="return confirm('<?= $active?'Deactivate':'Restore' ?> this user course access? History will be preserved.')"><input type="hidden" name="action" value="course_access"><input type="hidden" name="user" value="<?= e($userId) ?>"><input type="hidden" name="course" value="<?= e($slug) ?>"><input type="hidden" name="access" value="<?= $active?'revoke':'restore' ?>"><button class="btn <?= $active?'':'restore' ?>" type="submit"><?= $active?'Deactivate':'Restore' ?></button></form></td></tr><?php endforeach; ?></tbody></table><?php endif; ?></section><section class="panel"><h2>Subscriptions</h2><?php if($subscriptions===[]): ?><p class="muted">No subscription records.</p><?php else: ?><table><tr><th>Plan</th><th>Status</th><th>Amount</th><th>Start</th><th>Expires</th><th>Order</th></tr><?php foreach($subscriptions as $subscription): ?><tr><td><?= e((string)($subscription['plan_name']??$subscription['plan_slug']??'Subscription')) ?></td><td><?= e((string)$subscription['status']) ?></td><td>₹<?= number_format(((int)($subscription['final_amount_paise']??0))/100,2) ?></td><td><?= e((string)$subscription['start_at']) ?></td><td><?= e((string)$subscription['expires_at']) ?></td><td><?= e((string)($subscription['order_id']??'')) ?></td></tr><?php endforeach; ?></table><?php endif; ?></section><section class="panel"><h2>Orders and invoices</h2><?php if(empty($selected['orders'])): ?><p class="muted">No orders.</p><?php else: ?><table><tr><th>Product</th><th>Amount</th><th>Status</th><th>Date</th><th>Invoice</th></tr><?php foreach((array)$selected['orders'] as $order): ?><tr><td><?= e((string)$order['product']) ?></td><td>₹<?= e((string)$order['amount']) ?></td><td><?= e((string)$order['status']) ?></td><td><?= e((string)$order['created_at']) ?></td><td><a class="btn" href="invoice.php?id=<?= e((string)$order['id']) ?>">View invoice</a></td></tr><?php endforeach; ?></table><?php endif; ?></section></main></body></html>
